package fr.cercle.tourderole;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.webkit.MimeTypeMap;import java.io.*;
public class FileBridge extends ContentProvider{
public boolean onCreate(){return true;}public static Uri uri(Context c,String rel){return new Uri.Builder().scheme("content").authority(c.getPackageName()+".files").path(rel).build();}
private File resolve(Uri u)throws FileNotFoundException{try{File base=getContext().getFilesDir(),f=new File(base,u.getPath().substring(1));if(!f.getCanonicalPath().startsWith(base.getCanonicalPath()+File.separator)||!f.isFile())throw new IOException();return f;}catch(Exception e){throw new FileNotFoundException("Fichier inaccessible");}}
public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{if(!mode.equals("r"))throw new FileNotFoundException("Lecture seule");return ParcelFileDescriptor.open(resolve(u),ParcelFileDescriptor.MODE_READ_ONLY);}
public String getType(Uri u){String p=u.getLastPathSegment(),ext=p.contains(".")?p.substring(p.lastIndexOf('.')+1).toLowerCase():"";String mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);return mime==null?"application/octet-stream":mime;}
public Cursor query(Uri u,String[] cols,String selection,String[] args,String sort){try{File f=resolve(u);String[] names=cols==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:cols;MatrixCursor cur=new MatrixCursor(names);Object[] values=new Object[names.length];for(int i=0;i<names.length;i++)values[i]=names[i].equals(OpenableColumns.SIZE)?f.length():f.getName();cur.addRow(values);return cur;}catch(Exception e){return null;}}
public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}}
